-- 2026-10-28: all legacy equipment icons replaced with exact owner ZIP images.
-- This migration changes the icon dictionary only, never equipment ownership or allocation history.
BEGIN;
UPDATE public.equipment_item_catalog
  SET icon_verified = false, updated_at = now()
  WHERE icon_asset IN (
    '/equipment/icons/market-hero-30.webp',
    '/equipment/icons/market-rare-49.webp',
    '/equipment/icons/assassin-sprite.webp',
    '/equipment/icons/armor-hero-20261028.webp',
    '/equipment/icons/armor-rare-20261028.webp'
  );
ON CONFLICT (item_id) DO UPDATE SET
  item_name=EXCLUDED.item_name, slot=EXCLUDED.slot, rarity=EXCLUDED.rarity,
  tier=EXCLUDED.tier, equipment_kind=EXCLUDED.equipment_kind, job_class=EXCLUDED.job_class,
  icon_asset=EXCLUDED.icon_asset, sprite_index=EXCLUDED.sprite_index,
  sprite_columns=EXCLUDED.sprite_columns, icon_verified=EXCLUDED.icon_verified,updated_at=now();
COMMIT;
